// Build the canonical ground-truth row per shipment and the list of shipments to run.
// Canonical = last row with is_exception === 'YES'; if none, the (last) NO row.
const rows = $input.all().map(i => i.json);
const byShip = {};
for (const r of rows) {
  const sid = (r.shipment_id || '').trim();
  if (!sid) continue;
  (byShip[sid] = byShip[sid] || []).push(r);
}
const out = [];
for (const sid of Object.keys(byShip)) {
  const grp = byShip[sid];
  const yes = grp.filter(r => String(r.is_exception).toUpperCase() === 'YES');
  const canonical = yes.length ? yes[yes.length - 1] : grp[grp.length - 1];
  out.push({ json: {
    target_shipment_id: sid,
    gt_is_exception: String(canonical.is_exception || '').toUpperCase(),
    gt_resolution: canonical.expected_resolution || 'N/A',
    gt_tone: canonical.expected_tone || 'N/A',
    gt_should_escalate: String(canonical.should_escalate || '').toUpperCase() || 'N/A',
  }});
}
return out;

function clean(value, fallback = '') {
  if (value === null || value === undefined) return fallback;

  if (typeof value === 'string') {
    return value.replace(/^=/, '').trim();
  }

  return value;
}

function norm(value) {
  return String(clean(value, ''))
    .trim()
    .toUpperCase();
}

function toEscalationBool(value) {
  const text = norm(value);

  if (text === 'YES' || text === 'TRUE') return true;
  if (text === 'NO' || text === 'FALSE') return false;
  if (text === 'N/A' || text === 'NA' || text === '') return null;

  return null;
}

function pct(numerator, denominator) {
  if (!denominator) return 100;
  return Math.round((numerator / denominator) * 10000) / 100;
}

function avg(values) {
  const nums = values
    .map(v => Number(v))
    .filter(v => Number.isFinite(v));

  if (!nums.length) return 0;

  return Math.round((nums.reduce((a, b) => a + b, 0) / nums.length) * 100) / 100;
}

function toArray(value) {
  if (Array.isArray(value)) return value;

  if (value === null || value === undefined) return [];

  const text = String(value)
    .replace(/^=/, '')
    .trim();

  if (!text) return [];

  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed;
  } catch (error) {}

  return text
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
}

function buildToolChecker(toolsUsed) {
  const normalizedTools = toArray(toolsUsed).map(t =>
    String(t)
      .replace(/^=/, '')
      .trim()
      .toLowerCase()
  );

  const aliases = {
    Tool_customer_profile_lookup: [
      'tool_customer_profile_lookup',
      'customer_profile_lookup',
      'customer profile lookup'
    ],
    Tool_locker_availability: [
      'tool_locker_availability',
      'locker_availability',
      'locker availability'
    ],
    check_escalation_rules: [
      'check_escalation_rules',
      'escalation_rules',
      'check escalation rules'
    ],
    resolution_agent: [
      'resolution_agent',
      'resolution agent'
    ],
    communication_agent: [
      'communication_agent',
      'communication agent'
    ]
  };

  return function hasTool(expectedTool) {
    const expectedAliases = aliases[expectedTool] || [expectedTool.toLowerCase()];
    return expectedAliases.some(alias => normalizedTools.includes(alias.toLowerCase()));
  };
}

function deriveExpectedTools(item) {
  const gtException = norm(item.gt_is_exception || item.ground_truth_is_exception);
  const predictedException = norm(item.is_exception);

  if (gtException === 'NO' || predictedException === 'NO') {
    return [];
  }

  const expectedTools = [
    'Tool_customer_profile_lookup',
    'check_escalation_rules',
    'resolution_agent',
    'communication_agent'
  ];

  const resolution = norm(item.resolution || item.gt_resolution || item.ground_truth_resolution);
  const citationsText = toArray(item.playbook_citations).join(' ').toLowerCase();
  const rationaleText = String(item.rationale || '').toLowerCase();

  const needsLocker =
    resolution === 'REROUTE_TO_LOCKER' ||
    citationsText.includes('locker reroute') ||
    rationaleText.includes('locker');

  if (needsLocker) {
    expectedTools.push('Tool_locker_availability');
  }

  return expectedTools;
}

function evaluateTools(item) {
  const toolsUsed = toArray(item.tools_used);
  const expectedTools = deriveExpectedTools(item);
  const hasTool = buildToolChecker(toolsUsed);

  const isRoutine =
    norm(item.gt_is_exception || item.ground_truth_is_exception) === 'NO' ||
    norm(item.is_exception) === 'NO';

  if (isRoutine) {
    return {
      expected_tools: [],
      missing_tools: [],
      unexpected_tools: toolsUsed.length ? toolsUsed : [],
      tool_match: toolsUsed.length === 0
    };
  }

  const missingTools = expectedTools.filter(tool => !hasTool(tool));

  const needsLocker = expectedTools.includes('Tool_locker_availability');
  const hasLocker = hasTool('Tool_locker_availability');

  const unexpectedTools = [];

  if (!needsLocker && hasLocker) {
    unexpectedTools.push('Tool_locker_availability');
  }

  return {
    expected_tools: expectedTools,
    missing_tools: missingTools,
    unexpected_tools: unexpectedTools,
    tool_match: missingTools.length === 0 && unexpectedTools.length === 0
  };
}

const items = $input.all().map(item => item.json || {});

const perShipment = items.map(item => {
  const shipmentId = clean(item.shipment_id);

  const predException = norm(item.is_exception);
  const gtException = norm(item.gt_is_exception || item.ground_truth_is_exception);

  const predResolution = norm(item.resolution);
  const gtResolution = norm(item.gt_resolution || item.ground_truth_resolution);

  const predTone = norm(item.tone_label);
  const gtTone = norm(item.gt_tone || item.ground_truth_tone);

  const predEscalated = item.escalated === true;
  const gtEscalated = toEscalationBool(item.gt_should_escalate || item.ground_truth_should_escalate);

  const excMatch = predException === gtException;
  const resMatch = predResolution === gtResolution;
  const toneMatch = predTone === gtTone;

  const escMatch =
    gtEscalated === null
      ? null
      : predEscalated === gtEscalated;

  const toolEval = evaluateTools(item);

  const messageOk =
    gtException === 'YES'
      ? String(item.customer_message || '').trim().length > 0
      : true;

  const taskComplete =
    excMatch &&
    resMatch &&
    toneMatch &&
    escMatch !== false &&
    messageOk;

  const coherence = Number(item.coherence_score || 0);

  return {
    shipment_id: shipmentId,
    is_exception: `${predException} / ${gtException}`,
    resolution: `${predResolution} / ${gtResolution}`,
    tone: `${predTone} / ${gtTone}`,
    escalate: `${predEscalated} / ${clean(item.gt_should_escalate || item.ground_truth_should_escalate)}`,
    tools_used: toArray(item.tools_used),
    expected_tools: toolEval.expected_tools,
    missing_tools: toolEval.missing_tools,
    unexpected_tools: toolEval.unexpected_tools,
    exc_match: excMatch,
    res_match: resMatch,
    tone_match: toneMatch,
    esc_match: escMatch,
    tool_match: toolEval.tool_match,
    task_complete: taskComplete,
    coherence,
    rationale: clean(item.rationale, ''),
    playbook_citations: toArray(item.playbook_citations)
  };
});

const n = perShipment.length;

const taskCompleteCount = perShipment.filter(r => r.task_complete).length;
const excMatchCount = perShipment.filter(r => r.exc_match).length;
const resMatchCount = perShipment.filter(r => r.res_match).length;
const toneMatchCount = perShipment.filter(r => r.tone_match).length;
const toolMatchCount = perShipment.filter(r => r.tool_match).length;

const escalationRows = perShipment.filter(r => r.esc_match !== null);
const escalationMatchCount = escalationRows.filter(r => r.esc_match === true).length;

return [
  {
    json: {
      summary: {
        n_shipments: n,
        task_completion_rate_pct: pct(taskCompleteCount, n),
        escalation_accuracy_pct: pct(escalationMatchCount, escalationRows.length),
        resolution_accuracy_pct: pct(resMatchCount, n),
        tone_accuracy_pct: pct(toneMatchCount, n),
        tool_call_accuracy_pct: pct(toolMatchCount, n),
        mean_coherence_1to5: avg(perShipment.map(r => r.coherence))
      },
      per_shipment: perShipment
    }
  }
];

function clean(value, fallback = '') {
  if (value === null || value === undefined) return fallback;

  if (typeof value === 'string') {
    return value.replace(/^=/, '').trim();
  }

  return value;
}

function toBool(value) {
  if (value === true) return true;
  if (value === false) return false;

  const text = String(value ?? '')
    .replace(/^=/, '')
    .trim()
    .toLowerCase();

  return text === 'true' || text === 'yes';
}

function toArray(value) {
  if (Array.isArray(value)) return value;

  if (value === null || value === undefined) return [];

  const text = String(value)
    .replace(/^=/, '')
    .trim();

  if (!text) return [];

  try {
    const parsed = JSON.parse(text);
    if (Array.isArray(parsed)) return parsed;
  } catch (error) {}

  return text
    .split(',')
    .map(s => s.trim())
    .filter(Boolean);
}

function parseCoherence(value) {
  const raw = String(value || '').trim();

  try {
    return JSON.parse(raw);
  } catch (error) {
    const match = raw.match(/\{[\s\S]*\}/);
    if (match) {
      try {
        return JSON.parse(match[0]);
      } catch (innerError) {}
    }
  }

  return {
    coherence_score: 0,
    justification: 'Coherence judge output could not be parsed.'
  };
}

const coherenceItems = $input.all();
const predictionItems = $('Run Main Pipeline per Shipment').all();
const groundTruthItems = $('Smoke Test Filter code').all();

return coherenceItems.map((item, index) => {
  const pred = predictionItems[index]?.json || {};
  const gt = groundTruthItems[index]?.json || {};
  const coherence = parseCoherence(item.json.text);

  const score = Number(clean(coherence.coherence_score, 0));

  const shipmentId = clean(
    pred.shipment_id ||
    gt.target_shipment_id ||
    gt.shipment_id ||
    ''
  );

  const groundTruthReasoning = clean(
    gt.ground_truth_reasoning ||
    gt.gt_reasoning ||
    gt.expected_reasoning ||
    gt.reasoning ||
    gt.ground_truth_rationale ||
    gt.expected_rationale ||
    '',
    ''
  );

  return {
    json: {
      shipment_id: shipmentId,

      is_exception: clean(pred.is_exception),
      resolution: clean(pred.resolution),
      escalated: toBool(pred.escalated),
      tone_label: clean(pred.tone_label, 'N/A') || 'N/A',
      channel: clean(pred.channel, 'N/A') || 'N/A',
      customer_message: clean(pred.customer_message, ''),
      rationale: clean(pred.rationale, ''),

      tools_used: toArray(pred.tools_used),
      playbook_citations: toArray(pred.playbook_citations),

      critic_resolution: pred.critic_resolution || null,
      critic_communication: pred.critic_communication || null,

      coherence_score: Number.isFinite(score) ? score : 0,
      coherence_justification: clean(coherence.justification, ''),

      ground_truth_is_exception: clean(gt.gt_is_exception || gt.is_exception),
      ground_truth_resolution: clean(gt.gt_resolution || gt.expected_resolution),
      ground_truth_tone: clean(gt.gt_tone || gt.expected_tone),
      ground_truth_should_escalate: clean(gt.gt_should_escalate || gt.should_escalate),
      ground_truth_reasoning: groundTruthReasoning,

      gt_is_exception: clean(gt.gt_is_exception || gt.is_exception),
      gt_resolution: clean(gt.gt_resolution || gt.expected_resolution),
      gt_tone: clean(gt.gt_tone || gt.expected_tone),
      gt_should_escalate: clean(gt.gt_should_escalate || gt.should_escalate)
    }
  };
});
